// Synthetic public HTML for isolated browser tests. No external requests or API keys.
export const esc = value => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function searchPage(items, { page=1, pageSize=items.length || 2, total=items.length, stores=false } = {}) {
 return `<html><body><form id="Search3_Form"><input name="ViewRowCount" value="${pageSize}"><input name="page" value="${page}"></form><p>검색한 결과 총 ${total}건입니다.</p><a class="numon">${page}</a>${items.map(item=>`<div class="ss_book_box" itemid="${item.itemId}"><input name="chkCart.${esc(item.isbn13)}"><div class="ss_book_list"><li><a class="bo3">${esc(item.title)}</a></li><li>${esc(item.author)} | 출판사 | ${item.pubDate?.replace(/^(\d+)-(\d+)(?:-(\d+))?$/,(_,y,m,d)=>`${y}년 ${m}월${d?` ${d}일`:''}`)??''}</li><span class="ss_p2">${item.priceSales??1000}원</span></div>${item.cover?`<img class="i_cover" src="${esc(item.cover)}">`:''}${stores?`<a class="usedshop_off_text3" href="https://www.aladin.co.kr/usedstore/wproduct.aspx?ItemId=${item.itemId}&amp;OffCode=SEOUL">갱신 서울점</a>`:''}</div>`).join('')}</body></html>`;
}
export function productPage(item) {
 return `<html><head>${Object.entries({url:`https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=${item.itemId}`,title:item.title,author:item.author,description:item.description,barcode:item.isbn13,price:item.priceSales??1000,site_name:'aladin',image:item.cover??''}).map(([key,value])=>`<meta property="og:${key}" content="${esc(value)}">`).join('')}</head><body><span class="Ere_sub2_title">${esc(item.pubDate)}</span></body></html>`;
}
export function usedPage(itemId, { count, page=1, pages=1, offers=[{kind:'direct'},{kind:'store'}], totals }={}) {
 const counts=totals??{direct:offers.filter(o=>o.kind==='direct').length,store:offers.filter(o=>o.kind==='store').length,private:offers.filter(o=>o.kind==='private').length};
 count??=counts.direct+counts.store+counts.private;
 return `<html><body><input name="ItemId" value="${itemId}"><input name="TabType" value="0"><input name="page" value="${page}"><a class="Ere_usedsell_tab_on">전체 중고 (${count})</a>${[['direct','알라딘 중고'],['store','중고매장 이 광활한 우주점'],['private','판매자 중고']].map(([key,label])=>`<a class="Ere_usedsell_tab">${label} (${counts[key]})</a>`).join('')}<div class="Ere_usedsell_num_box"><div class="nright_text">/ ${pages}페이지</div></div>${count?`<div class="Ere_usedsell_table"><table>${offers.map((offer,i)=>`<tr><td class="sell_tableCF1"></td><td><div class="info"><a href="/shop/wproduct.aspx?ItemId=${offer.id??`${itemId}${page}${i}`}">갱신된 테스트 재고</a></div><span class="Ere_sub_top">상</span><div class="price"><span class="Ere_fs20">${offer.kind==='store'?'1700':'2300'}</span></div><div class="seller">${offer.kind==='direct'?'<div class="Ere_used_aladin"><a href="/shop/usedshop/wshopitem.aspx?SC=0">알라딘 직접 배송</a></div>':offer.kind==='store'?'<div class="Ere_used_store">이 광활한 우주점</div><div class="Ere_store_name"><a href="/shop/usedshop/wshopitem.aspx?SC=123">중고매장 갱신 서울점</a></div>':'<a href="/shop/usedshop/wshopitem.aspx?SC=456">알라딘 이름을 쓴 판매자</a><div class="Ere_used_special">전문셀러</div>'}</div></td></tr>`).join('')}</table></div>`:'등록된 중고상품이 없습니다.'}</body></html>`;
}
export function branchPage() {
 return `<html><body><span class="ss_p4">1부</span><div class="ss_book_box"><span class="ss_p2"><b>1,700원</b></span><span class="ss_p4">1부</span><span class="us_f_bob">상</span></div></body></html>`;
}
